---

This is a correctness-critical function: it gates what a human reviewer can write into the resolved hierarchy, and per the doc comment it **must stay in lockstep with `engine/pipeline/normalize.py`**. Zero tests today means that lockstep is unverified.

Untested edge cases:
- Suffix stripping order (`"Trellis Labs Pvt Ltd"` → must strip `"pvt ltd"` as one unit, not leave `"pvt"` dangling)
- Value that **is** a suffix verbatim (`"Ltd"` alone — must not be stripped to `""`)
- Unicode normalization (`"Ｃａｆé"` full-width / combining diacritics via NFKD)
- Punctuation-only input → folds to empty string
- `checkObservedValue` with empty `observed` array (orphan case — nothing to choose from)
- `checkObservedValue` where candidate matches via fold but not exact string
- Candidate that's whitespace-only
- Duplicate conflict: two values on one side, candidate matches the second not the first

```ts
// lib/validate-value.test.ts
import { describe, it, expect } from "vitest";
import { foldValue, checkObservedValue, observedValues } from "@/lib/validate-value";

describe("foldValue", () => {
  it("strips a single legal suffix", () => {
    expect(foldValue("Acme Inc.")).toBe("acme");
  });

  it("strips stacked suffixes longest-first (pvt ltd, not pvt)", () => {
    expect(foldValue("Trellis Labs Pvt Ltd")).toBe("trellis labs");
  });

  it("does not strip when the whole value IS a suffix", () => {
    expect(foldValue("Ltd")).toBe("ltd");
  });

  it("folds punctuation and case differences to the same value", () => {
    expect(foldValue("ACME-INC")).toBe(foldValue("ACME INC"));
  });

  it("collapses to empty string for punctuation-only input", () => {
    expect(foldValue("---")).toBe("");
  });

  it("normalizes unicode diacritics via NFKD", () => {
    expect(foldValue("Café Corp")).toBe(foldValue("Cafe Corp"));
  });
});

describe("checkObservedValue", () => {
  it("accepts an exact match", () => {
    const result = checkObservedValue("ACC-4417", ["ACC-4417", "ACC-2201"]);
    expect(result).toEqual({ ok: true, matches: "ACC-4417" });
  });

  it("accepts a legal normalization of an observed value", () => {
    const result = checkObservedValue("acme inc", ["Acme Inc."]);
    expect(result.ok).toBe(true);
  });

  it("rejects an invented value not present on either side", () => {
    const result = checkObservedValue("ACC-9999", ["ACC-4417", "ACC-2201"]);
    expect(result).toEqual({ ok: false, reason: expect.stringContaining("Must be one of") });
  });

  it("rejects empty/whitespace input", () => {
    expect(checkObservedValue("   ", ["ACC-4417"]).ok).toBe(false);
  });

  it("rejects when neither side holds a value (orphan)", () => {
    const result = checkObservedValue("anything", []);
    expect(result).toEqual({ ok: false, reason: expect.stringContaining("nothing to choose from") });
  });

  it("matches the second of two duplicate-side values", () => {
    const result = checkObservedValue("ACC-2201", ["ACC-4417", "ACC-2201"]);
    expect(result).toEqual({ ok: true, matches: "ACC-2201" });
  });
});

describe("observedValues", () => {
  it("flattens both sides and drops blanks", () => {
    const row = { a: { values: ["X", ""] }, b: { values: ["Y"] } };
    expect(observedValues(row)).toEqual(["X", "Y"]);
  });
});
```

No tests for the O(n) prefix/suffix diff that drives the signature UI element.

Untested edge cases:
- Identical values → all prefix, empty middle/suffix
- Completely disjoint values (`"APAC"` vs `"XYZQ"`) → empty prefix/suffix
- One string empty
- Overlapping prefix/suffix windows (`"aa"` vs `"aaa"` — prefix and suffix scans could double-count)
- Prefix and suffix matches that would overlap if not bounded by `max - prefix`

```ts
// lib/diff-chars.test.ts
import { describe, it, expect } from "vitest";
import { diffSegments } from "@/lib/diff-chars";

describe("diffSegments", () => {
  it("returns all-prefix for identical values", () => {
    expect(diffSegments("Acme", "Acme")).toEqual({ prefix: "Acme", middle: "", suffix: "" });
  });

  it("finds shared prefix and suffix around a differing middle", () => {
    expect(diffSegments("APAC-SOUTH", "APAC-NORTH")).toEqual({
      prefix: "APAC-",
      middle: "SOUTH",
      suffix: "",
    });
  });

  it("handles completely disjoint strings", () => {
    expect(diffSegments("ABCD", "WXYZ")).toEqual({ prefix: "", middle: "ABCD", suffix: "" });
  });

  it("handles one empty string", () => {
    expect(diffSegments("", "Acme")).toEqual({ prefix: "", middle: "", suffix: "" });
  });

  it("does not double-count overlapping prefix/suffix windows", () => {
    // "aa" vs "aaa": prefix scan alone would claim both chars; suffix must be bounded
    expect(diffSegments("aa", "aaa")).toEqual({ prefix: "aa", middle: "", suffix: "" });
  });
});
```

Zero coverage on date/number formatting used across every screen.

```ts
// lib/format.test.ts
import { describe, it, expect } from "vitest";
import {
  shortRunId, formatElapsed, formatCount, formatStat,
  formatClockTime, formatTimestamp, formatRelative, formatConfidence,
} from "@/lib/format";

describe("shortRunId", () => {
  it("strips hyphens and interpunct-joins first 4 and next 2 chars", () => {
    expect(shortRunId("a41f1234-c9ab-...")).toBe("a41f·c9");
  });
});

describe("formatElapsed", () => {
  it("formats sub-hour as mm:ss", () => expect(formatElapsed(65_000)).toBe("01:05"));
  it("formats past an hour as h:mm:ss", () => expect(formatElapsed(3_661_000)).toBe("1:01:01"));
  it("clamps negative ms to zero", () => expect(formatElapsed(-500)).toBe("00:00"));
  it("handles exactly zero", () => expect(formatElapsed(0)).toBe("00:00"));
});

describe("formatStat", () => {
  it("renders em dash for null", () => expect(formatStat(null)).toBe("—"));
  it("renders em dash for undefined", () => expect(formatStat(undefined)).toBe("—"));
  it("renders 0 distinctly from unknown", () => expect(formatStat(0)).toBe("0"));
  it("adds thousands separators", () => expect(formatStat(12345)).toBe("12,345"));
});

describe("formatRelative", () => {
  const now = new Date("2026-08-08T12:00:00Z");
  it("renders 'just now' under a minute", () => {
    expect(formatRelative(new Date("2026-08-08T11:59:30Z"), now)).toBe("just now");
  });
  it("renders minutes", () => {
    expect(formatRelative(new Date("2026-08-08T11:55:00Z"), now)).toBe("5m ago");
  });
  it("renders hours", () => {
    expect(formatRelative(new Date("2026-08-08T09:00:00Z"), now)).toBe("3h ago");
  });
  it("renders days", () => {
    expect(formatRelative(new Date("2026-08-06T12:00:00Z"), now)).toBe("2d ago");
  });
  it("handles a future date (negative delta) without throwing", () => {
    expect(() => formatRelative(new Date("2026-08-08T13:00:00Z"), now)).not.toThrow();
  });
});

describe("formatConfidence", () => {
  it("always renders two decimals", () => expect(formatConfidence(0.9)).toBe("0.90"));
  it("handles 0 and 1 boundaries", () => {
    expect(formatConfidence(0)).toBe("0.00");
    expect(formatConfidence(1)).toBe("1.00");
  });
});
