Missing-error-handling-shaped gap: precedence order (`username` > `email` > `fallback`) is unverified, including the falsy-but-present cases (`username: ""`).

```ts
// lib/reviewer-label.test.ts
import { describe, it, expect } from "vitest";
import { reviewerLabel } from "@/lib/reviewer-label";

describe("reviewerLabel", () => {
  it("prefers username", () => {
    expect(reviewerLabel({ username: "j.rao", primaryEmailAddress: { emailAddress: "j@x.com" } }, "uid")).toBe("j.rao");
  });
  it("falls back to email when no username", () => {
    expect(reviewerLabel({ username: null, primaryEmailAddress: { emailAddress: "j@x.com" } }, "uid")).toBe("j@x.com");
  });
  it("falls back to the userId when user is null", () => {
    expect(reviewerLabel(null, "uid-123")).toBe("uid-123");
  });
  it("falls back to userId when username is an empty string", () => {
    // "" is falsy but present — verifies ?? not || semantics aren't silently broken
    expect(reviewerLabel({ username: "", primaryEmailAddress: null }, "uid-123")).toBe("uid-123");
  });
  it("falls back to userId when email object exists but emailAddress is null", () => {
    expect(reviewerLabel({ username: null, primaryEmailAddress: { emailAddress: null } }, "uid-123")).toBe("uid-123");
  });
});
```

Four distinct branches (unresolved / rule-decided / model-proposed / escalated-no-value) are entirely untested, and the doc comment states the trace is *derived, never guessed* — meaning a bug here silently misleads a reviewer about how a decision was made.

```ts
// lib/rule-trace.test.ts
import { describe, it, expect } from "vitest";
import { deriveRuleTrace } from "@/lib/rule-trace";
import type { QueueRow } from "@/types/queue";

const baseRow = { field: "parentExternalId", entityType: "account" } as Partial<QueueRow>;

describe("deriveRuleTrace", () => {
  it("shows 'not yet resolved' when resolution is null", () => {
    const trace = deriveRuleTrace({ ...baseRow, resolution: null } as QueueRow);
    expect(trace).toEqual([
      { node: "classify", detail: "parentExternalId/account → not yet resolved", ran: false },
    ]);
  });

  it("traces a rule-decided resolution through apply, skipping propose/validate as ran:false/true correctly", () => {
    const trace = deriveRuleTrace({
      ...baseRow,
      resolution: {
        appliedRuleId: "rule-1", appliedRuleStrategy: "most_recent",
        proposedValue: "ACC-2201", confidence: 1,
      },
    } as QueueRow);
    expect(trace.find(s => s.node === "apply")?.ran).toBe(true);
    expect(trace.find(s => s.node === "propose")?.ran).toBe(false);
    expect(trace.find(s => s.node === "validate")?.ran).toBe(true);
  });

  it("traces a model-proposed resolution (no rule matched)", () => {
    const trace = deriveRuleTrace({
      ...baseRow,
      resolution: { appliedRuleId: null, appliedRuleStrategy: null, proposedValue: "ACC-2201", confidence: 0.82 },
    } as QueueRow);
    expect(trace.find(s => s.node === "propose")?.ran).toBe(true);
    expect(trace.find(s => s.node === "propose")?.detail).toContain("0.82");
  });

  it("traces an escalated conflict with no proposed value (nothing ran past classify)", () => {
    const trace = deriveRuleTrace({
      ...baseRow,
      resolution: { appliedRuleId: null, appliedRuleStrategy: null, proposedValue: "", confidence: 0 },
    } as QueueRow);
    expect(trace.find(s => s.node === "apply")?.ran).toBe(false);
    expect(trace.find(s => s.node === "propose")?.ran).toBe(false);
    expect(trace.find(s => s.node === "validate")?.ran).toBe(false);
  });
});
```

12+ independent conditional fields assembled in order; none tested. Highest-risk gaps: the `from`/`to` three-way branch, and unknown/malformed `detail` keys being silently ignored (a design guarantee, currently unverified).

```ts
// lib/audit-detail.test.ts
import { describe, it, expect } from "vitest";
import { auditDetailParts, auditDetailLine, auditNote } from "@/lib/audit-detail";
import type { AuditEntry } from "@/types/resolution";

function entry(action: AuditEntry["action"], detail: Record<string, unknown>): AuditEntry {
  return { id: "1", runId: "r1", resolutionId: null, action, actor: "j.rao", detail, createdAt: new Date() };
}

describe("auditDetailParts", () => {
  it("returns empty array when detail has no recognized keys", () => {
    expect(auditDetailParts(entry("run_started", { unrelatedKey: "x" }))).toEqual([]);
  });

  it("shows 'from → to' when both proposed and chosen values differ", () => {
    const parts = auditDetailParts(entry("human_overridden", { proposedValue: "A", chosenValue: "B" }));
    expect(parts).toContain("A → B");
  });

  it("shows only chosen value when proposed equals chosen (approve)", () => {
    const parts = auditDetailParts(entry("human_approved", { proposedValue: "A", chosenValue: "A" }));
    expect(parts).toContain("A");
    expect(parts.find(p => p.includes("→"))).toBeUndefined();
  });

  it("shows nothing value-wise on reject (chosenValue explicitly null)", () => {
    const parts = auditDetailParts(entry("human_rejected", { proposedValue: "A", chosenValue: null }));
    expect(parts).toContain("A");
  });

  it("labels count with the action-specific noun", () => {
    const parts = auditDetailParts(entry("conflict_detected", { count: 41 }));
    expect(parts).toContain("41 conflicts");
  });

  it("falls back to bare count for actions with no noun mapping", () => {
    const parts = auditDetailParts(entry("run_started", { count: 41 }));
    expect(parts).toContain("41");
  });

  it("ignores wrong-typed values instead of throwing (count as string)", () => {
    expect(() => auditDetailParts(entry("run_started", { count: "41" as unknown as number }))).not.toThrow();
    expect(auditDetailParts(entry("run_started", { count: "41" as unknown as number }))).not.toContain("41");
  });

  it("renders previousStatus with underscores replaced", () => {
    const parts = auditDetailParts(entry("human_approved", { previousStatus: "auto_applied" }));
    expect(parts).toContain("was auto-applied");
  });
});

describe("auditDetailLine / auditNote", () => {
  it("joins parts with · ", () => {
    expect(auditDetailLine(entry("run_started", { externalId: "ACC-1", field: "name" }))).toBe("ACC-1 · name");
  });
  it("returns null when there are no parts", () => {
    expect(auditDetailLine(entry("run_started", {}))).toBeNull();
  });
  it("extracts the note separately from the summary parts", () => {
    expect(auditNote(entry("human_approved", { note: "looks right" }))).toBe("looks right");
    expect(auditDetailParts(entry("human_approved", { note: "looks right" }))).toContain("note attached");
  });
});
```

