Business-facing display logic with several branches (duplicate `from > to` math, orphan child-count pluralization, default-case severity split at 3).

```ts
// types/queue.test.ts
import { describe, it, expect } from "vitest";
import { conflictFieldLabel, severityReason } from "@/types/queue";

describe("conflictFieldLabel", () => {
  it("labels orphan as 'entity absent'", () => {
    expect(conflictFieldLabel({ field: "name", conflictClass: "orphan", a: { values: [], present: false }, b: { values: ["x"], present: true } })).toBe("entity absent");
  });
  it("labels duplicate collapse as 'N → M'", () => {
    expect(conflictFieldLabel({ field: "name", conflictClass: "duplicate", a: { values: ["1", "2"], present: true }, b: { values: ["1"], present: true } })).toBe("2 → 1");
  });
  it("labels duplicate with equal counts as 'duplicate record'", () => {
    expect(conflictFieldLabel({ field: "name", conflictClass: "duplicate", a: { values: ["1"], present: true }, b: { values: ["1"], present: true } })).toBe("duplicate record");
  });
  it("falls back to the field name for a plain field conflict", () => {
    expect(conflictFieldLabel({ field: "email", conflictClass: "cosmetic", a: { values: ["a"], present: true }, b: { values: ["b"], present: true } })).toBe("email");
  });
});

describe("severityReason", () => {
  it("pluralizes 'child' for exactly one child", () => {
    expect(severityReason({ conflictClass: "orphan", severity: 4, childCount: 1 })).toContain("1 child");
    expect(severityReason({ conflictClass: "orphan", severity: 4, childCount: 1 })).not.toContain("1 children");
  });
  it("pluralizes 'children' for zero and for >1", () => {
    expect(severityReason({ conflictClass: "orphan", severity: 3, childCount: 0 })).toBe("absent on one side, no children");
    expect(severityReason({ conflictClass: "orphan", severity: 4, childCount: 3 })).toContain("3 children");
  });
  it("distinguishes severity-3 default vs other default severities", () => {
    expect(severityReason({ conflictClass: "field", severity: 3, childCount: 0 } as any)).toContain("owns or is credited");
    expect(severityReason({ conflictClass: "field", severity: 1, childCount: 0 } as any)).toContain("non-rollup");
  });
});
```

