Untested error-handling scenarios:
- `ENGINE_URL` unset → throws `EngineUnreachableError` before any fetch
- `fetch` rejects (network error) → wrapped as `EngineUnreachableError` with cause
- `fetch` times out (`AbortSignal.timeout`) → message says "no response within 8s" specifically (the `describe()` branch keyed on `TimeoutError`)
- `response.ok` is false → error includes truncated (300-char) response body
- `response.ok` true but body fails schema validation → `EngineUnreachableError` about contract break
- `fetchEngineStatus`: any thrown error (network/timeout) is swallowed and returns `null`, never throws
- `fetchEngineStatus`: non-ok response returns `null`
- `fetchEngineStatus`: malformed JSON body returns `null` (not a thrown parse error)

```ts
// lib/server/engine.test.ts
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { startRun, fetchEngineStatus, EngineUnreachableError } from "@/lib/server/engine";

describe("startRun", () => {
  const OLD_ENV = process.env.ENGINE_URL;
  afterEach(() => { process.env.ENGINE_URL = OLD_ENV; vi.restoreAllMocks(); });

  it("throws EngineUnreachableError when ENGINE_URL is unset", async () => {
    delete process.env.ENGINE_URL;
    await expect(startRun("run-1")).rejects.toThrow(EngineUnreachableError);
  });

  it("wraps a network failure as EngineUnreachableError with the original cause", async () => {
    process.env.ENGINE_URL = "http://engine.test";
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(new Error("ECONNREFUSED")));
    await expect(startRun("run-1")).rejects.toThrow(/ECONNREFUSED/);
  });

  it("reports a timeout distinctly from other network errors", async () => {
    process.env.ENGINE_URL = "http://engine.test";
    const timeoutErr = Object.assign(new Error("aborted"), { name: "TimeoutError" });
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(timeoutErr));
    await expect(startRun("run-1")).rejects.toThrow(/no response within 8s/);
  });

  it("throws with a truncated response body when the engine rejects the run", async () => {
    process.env.ENGINE_URL = "http://engine.test";
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response("x".repeat(500), { status: 500 })));
    await expect(startRun("run-1")).rejects.toThrow(/500/);
  });

  it("throws a contract-break error when the 200 response fails schema validation", async () => {
    process.env.ENGINE_URL = "http://engine.test";
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(Response.json({ wrong: "shape" })));
    await expect(startRun("run-1")).rejects.toThrow(/unexpected body/);
