Untested, and its correctness (advisory lock + per-name versioning + single-active invariant) is a concurrency guarantee that a unit test with a mocked `tx` can only partially verify — this really wants an **integration test against real Postgres** with concurrent calls.

```ts
// lib/server/rulesets.integration.test.ts
// Requires a real (test) Postgres instance — this is the concurrency
// invariant the advisory lock exists to protect, and a mock cannot prove it.
import { describe, it, expect } from "vitest";
import { createRulesetVersion, listRulesets, getActiveRuleset } from "@/lib/server/rulesets";

describe("createRulesetVersion", () => {
  it("assigns version 1 to the first ruleset with a given name", async () => {
    const rs = await createRulesetVersion({ name: "default", rules: [] });
    expect(rs.version).toBe(1);
  });

  it("increments version for the same name and deactivates the previous version", async () => {
    const v1 = await createRulesetVersion({ name: "policy-x", rules: [] });
    const v2 = await createRulesetVersion({ name: "policy-x", rules: [] });
    expect(v2.version).toBe(v1.version + 1);
    const active = await getActiveRuleset();
    expect(active?.id).toBe(v2.id);
  });

  it("guarantees exactly one active ruleset across different names", async () => {
    await createRulesetVersion({ name: "policy-a", rules: [] });
    await createRulesetVersion({ name: "policy-b", rules: [] });
    const all = await listRulesets();
    expect(all.filter(r => r.isActive)).toHaveLength(1);
  });

  it("two concurrent saves of the same name never both become the same version (race)", async () => {
    const [a, b] = await Promise.all([
      createRulesetVersion({ name: "race-policy", rules: [] }),
      createRulesetVersion({ name: "race-policy", rules: [] }),
    ]);
    expect(a.version).not.toBe(b.version);
  });
});
