    await act(async () => {
      const promise = result.current.submit("c1", { action: "approve" });
      pendingDuring = result.current.pendingId;
      await promise;
    });

    expect(pendingDuring).toBe("c1");
    expect(result.current.pendingId).toBeNull();
  });

  it("records the server-returned status in `decided`, not an optimistic guess", async () => {
    vi.mocked(patchJson).mockResolvedValue({ ok: true, data: { conflictId: "c1", status: "overridden", reviewedBy: "j.rao" } });
    const { result } = renderHook(() => useReview());
    await act(async () => { await result.current.submit("c1", { action: "override", overrideValue: "X" }); });
    expect(result.current.decided["c1"]).toEqual({ status: "overridden", reviewedBy: "j.rao" });
  });

  it("leaves `decided` unchanged on a failed request (no optimistic rollback needed)", async () => {
    vi.mocked(patchJson).mockResolvedValue({ ok: false, message: "conflict already resolved" });
    const { result } = renderHook(() => useReview());
    let outcome;
    await act(async () => { outcome = await result.current.submit("c1", { action: "approve" }); });
    expect(outcome).toEqual({ ok: false, message: "conflict already resolved" });
    expect(result.current.decided["c1"]).toBeUndefined();
  });

  it("clears pendingId even when the request fails", async () => {
    vi.mocked(patchJson).mockResolvedValue({ ok: false, message: "err" });
    const { result } = renderHook(() => useReview());
    await act(async () => { await result.current.submit("c1", { action: "approve" }); });
    expect(result.current.pendingId).toBeNull();
  });

  it("merges decisions for multiple conflicts without clobbering earlier ones", async () => {
    vi.mocked(patchJson)
      .mockResolvedValueOnce({ ok: true, data: { conflictId: "c1", status: "approved", reviewedBy: "j.rao" } })
      .mockResolvedValueOnce({ ok: true, data: { conflictId: "c2", status: "rejected", reviewedBy: "j.rao" } });
    const { result } = renderHook(() => useReview());
    await act(async () => { await result.current.submit("c1", { action: "approve" }); });
    await act(async () => { await result.current.submit("c2", { action: "reject" }); });
    expect(Object.keys(result.current.decided)).toEqual(["c1", "c2"]);
  });
});
