    expect(parts).toContain("A → B");
  });

  it("shows only chosen value when proposed equals chosen (approve)", () => {
    const parts = auditDetailParts(entry("human_approved", { proposedValue: "A", chosenValue: "A" }));
    expect(parts).toContain("A");
    expect(parts.find(p => p.includes("→"))).toBeUndefined();
  });

  it("shows nothing value-wise on reject (chosenValue explicitly null)", () => {
    const parts = auditDetailParts(entry("human_rejected", { proposedValue: "A", chosenValue: null }));
    expect(parts).toContain("A");
  });

