    vi.mocked(patchJson).mockResolvedValue({ ok: false, message: "err" });
    const { result } = renderHook(() => useReview());
    await act(async () => { await result.current.submit("c1", { action: "approve" }); });
    expect(result.current.pendingId).toBeNull();
  });

  it("merges decisions for multiple conflicts without clobbering earlier ones", async () => {
    vi.mocked(patchJson)
      .mockResolvedValueOnce({ ok: true, data: { conflictId: "c1", status: "approved", reviewedBy: "j.rao" } })
      .mockResolvedValueOnce({ ok: true, data: { conflictId: "c2", status: "rejected", reviewedBy: "j.rao" } });
    const { result } = renderHook(() => useReview());
    await act(async () => { await result.current.submit("c1", { action: "approve" }); });
    await act(async () => { await result.current.submit("c2", { action: "reject" }); });
    expect(Object.keys(result.current.decided)).toEqual(["c1", "c2"]);
  });
});

// lib/api-client.test.ts
import { describe, it, expect, vi, afterEach } from "vitest";
import { postJson, patchJson } from "@/lib/api-client";

afterEach(() => vi.restoreAllMocks());

describe("api-client", () => {
  it("returns a network-error message when fetch itself throws", async () => {
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(new TypeError("Failed to fetch")));
    const result = await postJson("/api/sources", {});
    expect(result).toEqual({ ok: false, message: expect.stringContaining("Could not reach the server") });
  });

  it("surfaces the server error message and field issues on a non-ok response", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(Response.json({ error: "Invalid body", issues: { name: "required" } }, { status: 400 })));
    const result = await postJson("/api/sources", {});
    expect(result).toEqual({ ok: false, message: "Invalid body", issues: { name: "required" } });
  });

  it("falls back to a generic message when the error body has no `error` field", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response(null, { status: 500 })));
    const result = await postJson("/api/sources", {});
    expect(result).toEqual({ ok: false, message: "Request failed (500)." });
  });

  it("returns ok:true with parsed data on success", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(Response.json({ id: "1" })));
    const result = await postJson<{ id: string }>("/api/sources", { name: "x" });
    expect(result).toEqual({ ok: true, data: { id: "1" } });
  });

  it("uses PATCH method for patchJson", async () => {
    const fetchMock = vi.fn().mockResolvedValue(Response.json({}));
    vi.stubGlobal("fetch", fetchMock);
    await patchJson("/api/conflicts/1/resolution", { action: "approve" });
    expect(fetchMock).toHaveBeenCalledWith(expect.any(String), expect.objectContaining({ method: "PATCH" }));
  });

  it("does not throw when the response body is not valid JSON on success path", async () => {
    vi.stubGlobal("fetch", vi.fn().mockResolvedValue(new Response("not json", { status: 200 })));
    await expect(postJson("/api/sources", {})).resolves.toBeDefined();
  });
});
